(()=>{
  const root=document.querySelector('#org-app'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let user=null,data=null,page='home',editing=null,version=0;
  const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
  const field=(label,name,value='',type='text',attrs='')=>`<div><label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label></div>`;
  const choose=(label,name,rows,value='',optional=false)=>`<div><label>${label}<select name="${name}" ${optional?'':'required'}>${optional?'<option value="">Sem vínculo inicial</option>':'<option value="">Selecione…</option>'}${rows.map(([id,name])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(name)}</option>`).join('')}</select></label></div>`;
  const card=(title,body)=>`<section class="school-card"><h2>${title}</h2>${body}</section>`;
  const form=(kind,body,label)=>`<form class="school-form org-form" data-org-form="${kind}">${body}<button class="school-button" type="submit">${label}</button></form>`;
  const roles={teacher:'Professor',student:'Aluno',parent:'Responsável',institution:'Gestor da escola'},statusLabels={active:'Autorizada',pending:'Aguardando liberação',suspended:'Suspensa'};
  const credentials=()=>field('Nome do gestor / nome completo','name','', 'text','maxlength="120"')+field('Usuário ou e-mail','login','','text','minlength="3" maxlength="120" autocomplete="off"')+field('Senha inicial','password','','password','minlength="8" maxlength="128" autocomplete="new-password"');
  const schoolFields=(v={})=>field('Nome da escola','name',v.name||'')+choose('Situação do acesso','status',Object.entries(statusLabels),v.status||'pending')+choose('Ciclo da assinatura (visual)','billingCycle',[['monthly','Mensal'],['annual','Anual']],v.billing_cycle||'annual')+field('Capacidade contratada de alunos','studentLimit',v.student_limit||350,'number','min="1" max="100000" step="1"')+choose('Condição de pagamento (visual)','paymentOption',[['upfront','À vista'],['installments','Em até 12x']],v.payment_option||'upfront')+'<div class="org-price-preview" role="status"></div><p class="school-help">Até 350 alunos: R$ 1.600 à vista ou R$ 1.800 em até 12x. De 351 a 1.000: R$ 2.600 à vista ou R$ 2.800 em até 12x. Acima de 1.000, acrescente R$ 2,50 por aluno excedente. Valores de referência do plano, sem cobrança automática.</p>'+field('Média de referência','passGrade',v.pass_grade??6,'number','min="0" max="10" step="0.1"')+field('Frequência mínima de referência (%)','attendanceMin',v.attendance_min??75,'number','min="0" max="100" step="0.1"');
  function admin(){
    const schools=data.institutions;
    if(page==='new')return card('Cadastrar escola',form('school',schoolFields(),'Cadastrar escola'));
    if(page==='manager')return card('Criar acesso da instituição','<p>Este gestor poderá criar turmas, professores, alunos e responsáveis da escola selecionada. Os professores não criam mais contas.</p>'+form('manager',choose('Escola','institutionId',schools.map(s=>[s.id,s.name]))+credentials(),'Criar acesso da escola'));
    const selected=schools.find(s=>s.id===editing);
    return `<div class="org-notice">Assinaturas demonstrativas: os valores e ciclos são visuais. Não há cobrança, checkout ou pagamento automático.</div><div class="school-stats"><div class="school-stat"><strong>${schools.length}</strong><span>Escolas cadastradas</span></div><div class="school-stat"><strong>${schools.filter(s=>s.status==='active').length}</strong><span>Escolas autorizadas</span></div><div class="school-stat"><strong>${schools.reduce((n,s)=>n+s.student_count,0)}</strong><span>Alunos cadastrados</span></div></div>${selected?card('Editar escola e autorização',form('edit-school',schoolFields(selected),'Salvar autorização e plano')+'<button class="text-button" data-org-action="cancel">Cancelar edição</button>'):''}${card('Escolas e assinaturas',schools.length?schools.map(s=>`<article class="org-school-row"><div><h3>${esc(s.name)}</h3><p>${s.student_count} / ${s.student_limit} alunos · ${s.class_count} turmas · ${s.manager_count} acesso(s) de gestão</p><span class="school-pill">${statusLabels[s.status]}</span> <span class="school-pill">${s.billing_cycle==='annual'?'Anual':'Mensal'} · ${money(s.amount_cents)} / ciclo · visual</span></div><button class="school-button secondary" data-org-action="edit" data-id="${s.id}">Editar / autorizar</button></article>`).join(''):'<p>Nenhuma escola cadastrada. Cadastre a primeira escola no menu.</p>')}<p class="school-help">Para cadastros de versões anteriores: <button type="button" class="text-button" data-org-action="migrate">Importar cadastros anteriores preservando os dados</button></p>`;
  }
  function institution(){
    const {institution:s,classes,accounts,members,links}=data,students=accounts.filter(a=>a.role==='student'),teachers=accounts.filter(a=>a.role==='teacher'),parents=accounts.filter(a=>a.role==='parent'),classOptions=classes.map(c=>[c.id,c.name+' · '+c.academic_year]),name=id=>accounts.find(a=>a.id===id)?.name||'Conta';
    if(page==='classes')return `<div class="school-grid">${card('Criar turma',form('class',field('Nome da turma','name','', 'text','maxlength="120"')+field('Ano letivo','academicYear',new Date().getFullYear(),'number','min="2000" max="2100"'),'Criar turma'))}${card('Adicionar professor ou aluno já cadastrado',form('member',choose('Turma','classId',classOptions)+choose('Conta','accountId',accounts.filter(a=>['teacher','student'].includes(a.role)).map(a=>[a.id,a.name+' · '+roles[a.role]])),'Vincular à turma'))}</div>${card('Turmas da instituição',classes.map(c=>{const people=members.filter(m=>m.class_id===c.id).map(m=>accounts.find(a=>a.id===m.account_id)).filter(Boolean);return `<article class="org-school-row"><div><h3>${esc(c.name)} · ${c.academic_year}</h3><p>${people.filter(a=>a.role==='teacher').length} professores · ${people.filter(a=>a.role==='student').length} alunos</p><p>Professores: ${esc(people.filter(a=>a.role==='teacher').map(a=>a.name).join(', ')||'Ainda sem professor')}</p><p>Alunos: ${esc(people.filter(a=>a.role==='student').map(a=>a.name).join(', ')||'Ainda sem alunos')}</p></div></article>`;}).join('')||'<p>Crie uma turma para organizar os acessos.</p>')}`;
    if(page==='accounts')return `<div class="school-grid">${card('Criar conta na instituição',form('account',choose('Tipo de acesso','role',Object.entries(roles).filter(([r])=>r!=='institution'),'student')+credentials()+choose('Turma (professor ou aluno)','classId',classOptions,'',true)+choose('Aluno acompanhado (para responsável)','studentId',students.map(a=>[a.id,a.name]),'',true)+'<p class="school-help">Professor e aluno precisam de turma. Para responsáveis, escolha o aluno acompanhado ou faça o vínculo depois. Compartilhe as credenciais diretamente.</p>','Criar conta'))}${card('Contas da escola',accounts.map(a=>`<article class="org-school-row"><div><strong>${esc(a.name)}</strong><p>${esc(a.login)} · ${roles[a.role]}</p><p>${esc(members.filter(m=>m.account_id===a.id).map(m=>classes.find(c=>c.id===m.class_id)?.name).filter(Boolean).join(', '))}</p></div><span class="school-pill">Ativa</span></article>`).join(''))}</div>`;
    if(page==='links')return `<div class="school-grid">${card('Vincular pais aos alunos',form('link',choose('Pai, mãe ou responsável','parentId',parents.map(a=>[a.id,a.name+' · '+a.login]))+choose('Aluno','studentId',students.map(a=>[a.id,a.name+' · '+a.login])),'Salvar vínculo'))}${card('Vínculos familiares',links.map(l=>`<article class="org-school-row"><div><strong>${esc(name(l.parent_id))}</strong><p>Acompanha ${esc(name(l.student_id))}</p></div></article>`).join('')||'<p>Ainda não há vínculos familiares.</p>')}</div>`;
    return `<div class="org-notice">${esc(s.name)} · Acesso autorizado · ${s.billing_cycle==='annual'?'Plano anual':'Plano mensal'} · ${money(s.amount_cents)} por ciclo (visual, sem pagamento).</div><div class="school-stats">${[[classes.length,'Turmas'],[teachers.length,'Professores'],[students.length+' / '+s.student_limit,'Alunos / capacidade'],[parents.length,'Responsáveis']].map(([n,l])=>`<div class="school-stat"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div>${card('Organize sua instituição','<p>Crie as turmas, cadastre os professores e alunos em cada uma e conecte os responsáveis aos alunos. Uma turma pode ter vários professores. Todos os dados ficam restritos à escola e às turmas autorizadas.</p><div class="school-actions"><button class="school-button" data-org-page="classes">Gerenciar turmas</button><button class="school-button secondary" data-org-page="accounts">Criar contas</button><button class="school-button secondary" data-org-page="links">Vincular famílias</button></div>')}`;
  }
  function render(){const adminRole=user.role==='admin',pages=adminRole?[['home','Escolas e assinaturas'],['new','Cadastrar escola'],['manager','Acesso da instituição']]:[['home','Visão da escola'],['classes','Turmas'],['accounts','Professores, pais e alunos'],['links','Vínculos familiares']];root.innerHTML=`<div class="org-shell"><header class="org-header"><div><img src="brand-icon.svg" width="44" height="44" alt=""><div><strong>Conecta+</strong><small>${adminRole?'Administração da plataforma':esc(data.institution.name)}</small></div></div><button class="school-button secondary" data-org-action="logout">Sair</button></header><nav class="org-nav" aria-label="Gestão institucional">${pages.map(([id,l])=>`<button data-org-page="${id}" ${page===id?'aria-current="page"':''}>${l}</button>`).join('')}<button data-org-action="refresh">Atualizar</button></nav><main class="org-content"><h1>${pages.find(([id])=>id===page)?.[1]||'Gestão'}</h1><p id="org-status" role="status" aria-live="polite"></p>${adminRole?admin():institution()}</main></div>`;pricePreview();}
  function status(message){const node=root.querySelector('#org-status');if(node)node.textContent=message;}
  function pricePreview(){for(const form of root.querySelectorAll('[data-org-form="school"],[data-org-form="edit-school"]')){const limit=Number(form.elements.studentLimit.value),split=form.elements.paymentOption.value==='installments',total=limit<=350?(split?180000:160000):(split?280000:260000)+Math.max(0,limit-1000)*250;form.querySelector('.org-price-preview').textContent=money(total)+(split?' em até 12x de aproximadamente '+money(Math.round(total/12)):' à vista')+' · simulação sem cobrança';}}
  root.addEventListener('input',pricePreview);root.addEventListener('change',pricePreview);
  async function request(path,method='GET',body){const response=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível salvar.');return result;}
  async function refresh(){const v=++version;const next=await request(user.role==='admin'?'/api/institutions':'/api/institution');if(v!==version||!user)return;data=next;render();}
  root.addEventListener('click',async e=>{const node=e.target.closest('button');if(!node)return;if(node.dataset.orgPage){page=node.dataset.orgPage;editing=null;render();return;}if(node.dataset.orgAction==='migrate'){node.disabled=true;try{const result=await request('/api/admin/migrate-legacy','POST',{});await refresh();status(result.migrated+' escola(s) importada(s). Senhas, notas e vínculos foram preservados.');}catch(error){status(error.message);node.disabled=false;}return;}if(node.dataset.orgAction==='logout'){document.querySelector('#logout').click();return;}if(node.dataset.orgAction==='edit'){editing=node.dataset.id;render();return;}if(node.dataset.orgAction==='cancel'){editing=null;render();return;}if(node.dataset.orgAction==='refresh')try{await refresh();}catch(error){status(error.message);}});
  root.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.orgForm)return;e.preventDefault();const kind=form.dataset.orgForm,values=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');submit.disabled=true;status('Salvando…');try{const paths={school:'/api/institutions','edit-school':'/api/institutions/'+editing,manager:'/api/institutions/'+values.institutionId+'/manager',class:'/api/institution/classes',account:'/api/institution/accounts',member:'/api/institution/members',link:'/api/institution/links'};await request(paths[kind],kind==='edit-school'?'PATCH':'POST',values);editing=null;if(kind==='school'||kind==='edit-school')page='home';await refresh();status(['manager','account'].includes(kind)?'Acesso criado. Compartilhe o usuário e a senha diretamente; a senha não será exibida novamente.':'Salvo com sucesso.');}catch(error){status(error.message);submit.disabled=false;}});
  window.ConectaOrg={async open(account){user=account;page='home';editing=null;document.body.classList.add('portal-active');root.hidden=false;root.innerHTML='<div class="school-loading">Carregando gestão da escola…</div>';try{await refresh();}catch(error){root.innerHTML='<p class="org-error">'+esc(error.message)+'</p>'; }},close(){version++;user=null;data=null;root.hidden=true;root.replaceChildren();},refresh};
})();
